///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        tbx_isue_contn_search.hide();
        tbx_emph_invstg_search.hide();
        tbx_napprov_rsn_search.hide();
        scwin.setCode();
        //    fn_initSearchDate(tbx_COMITE_STRT_DD, tbx_COMITE_END_DD);
        //    fn_initSearchDate(tbx_BILL_STRT_DD, tbx_BILL_END_DD);

        $c.cm.PanelToGroupBox(panel_Top);
        await scwin.listSync();
        await scwin.setIssue();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60007.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if ($c.stf.compareFromToDate2(edt_BILL_STRT_DD, edt_BILL_END_DD) && $c.stf.compareFromToDate2(edt_COMITE_STRT_DD, edt_COMITE_END_DD)) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60007.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60007.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF60007.dts_List_OnLoadCompleted" });
    }
};

