/**
 * @method
 * @name cmb_PeriodTp1_onselchange
 * @description cmb_PeriodTp1 onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp1_onselchange = function() {
    try {
        let vTp = $c.cp.valueOfIndex(cmb_PeriodTp1, "VALUE", cmb_PeriodTp1.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_BILL_STRT_DD, edt_BILL_END_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF60007.cmb_PeriodTp1_onselchange" });
    }
};

