/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        if (colid !== 'COMITE_RSLT_NM') {
            return;
        }
        if (row > 0) {
            // 그리드에서 선택시
            scwin.setBzProcsNo(row);
        }
        scwin.fn_GetPar = scwin.getParDtl;
        scwin.fn_SetPar = undefined;
        const comite_tp_cd = dts_List.getCellData(row, "COMITE_TP_CD");
        if (comite_tp_cd === '1') {
            const options = {
                id: "ULDSTF05010_STK_ReadOnly",
                title: "위원회결과",
                type: "browserPopup",
                width: 560 + 10,
                height: 480 + 20,
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("../lstproc/ULDSTF05010_STK_ReadOnly.gfm", options);
        } else if (comite_tp_cd === '2') {
            const options = {
                id: "ULDSTF07108",
                title: "위원회결과",
                type: "browserPopup",
                width: 570 + 5,
                height: 750 + 35,
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("../lstinvstg/ULDSTF07108.gfm", options);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60007.grd_List_OnDblClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    let V_SECUGPR_ID = "";
    let V_LIST_TP_CLSS = "";
    let V_LIST_CLSS = "";
    let V_RSLT = " ";

    // 기업구분
    let previousChecked = false;
    V_SECUGPR_ID = " AND SECUGRP_ID IN ( ";
    if (chk_SECUGRP1.checked) {
        if (previousChecked) {
            V_SECUGPR_ID += ",  'ST' ";
        } else {
            V_SECUGPR_ID += " 'ST' ";
        }
        previousChecked = true;
    }
    if (chk_SECUGRP2.checked) {
        if (previousChecked) {
            V_SECUGPR_ID += ",  'FS' ";
        } else {
            V_SECUGPR_ID += " 'FS' ";
        }
        previousChecked = true;
    }
    if (chk_SECUGRP3.checked) {
        if (previousChecked) {
            V_SECUGPR_ID += ",  'DR' ";
        } else {
            V_SECUGPR_ID += " 'DR' ";
        }
        previousChecked = true;
    }
    if (chk_SECUGRP4.checked) {
        if (previousChecked) {
            V_SECUGPR_ID += ",  'RT' ";
        } else {
            V_SECUGPR_ID += " 'RT' ";
        }
        previousChecked = true;
    }
    if (previousChecked) {
        V_SECUGPR_ID += " ) ";
    } else {
        V_SECUGPR_ID = "";
    }

    /*상장구분*/
    let previousChecked = false;
    V_LIST_TP_CLSS = " AND LIST_TP_CLSS_CD IN ( ";
    if (chk_LIST_TP_CLSS1.checked) {
        if (previousChecked) {
            V_LIST_TP_CLSS += ",  '00' ";
        } else {
            V_LIST_TP_CLSS += " '00' ";
        }
        previousChecked = true;
    }
    if (chk_LIST_TP_CLSS2.checked) {
        if (previousChecked) {
            V_LIST_TP_CLSS += ",  '01' ";
        } else {
            V_LIST_TP_CLSS += " '01' ";
        }
        previousChecked = true;
    }
    if (chk_LIST_TP_CLSS3.checked) {
        if (previousChecked) {
            V_LIST_TP_CLSS += ",  '02' ";
        } else {
            V_LIST_TP_CLSS += " '02' ";
        }
        previousChecked = true;
    }
    if (chk_LIST_TP_CLSS4.checked) {
        if (previousChecked) {
            V_LIST_TP_CLSS += ",  '03' ";
        } else {
            V_LIST_TP_CLSS += " '03' ";
        }
        previousChecked = true;
    }
    /*if( chk_LIST_TP_CLSS5.checked){
    	if(previousChecked){
    			V_LIST_TP_CLSS  +=  ",  '04' ";
    	} else {
    			V_LIST_TP_CLSS  +=   " '04' ";
    	}
    	previousChecked = true;
    }*/
    if (chk_LIST_TP_CLSS6.checked) {
        if (previousChecked) {
            V_LIST_TP_CLSS += ",  '05' ";
        } else {
            V_LIST_TP_CLSS += " '05' ";
        }
        previousChecked = true;
    }
    if (chk_LIST_TP_CLSS7.checked) {
        if (previousChecked) {
            V_LIST_TP_CLSS += ",  '06' ";
        } else {
            V_LIST_TP_CLSS += " 06' ";
        }
        previousChecked = true;
    }
    if (previousChecked) {
        V_LIST_TP_CLSS += " ) ";
    } else {
        V_LIST_TP_CLSS = "";
    }

    /*상장유형*/
    let previousChecked = false;
    V_LIST_CLSS = " AND LIST_CLSS_CD IN ( ";
    if (chk_LIST_CLSS1.checked) {
        if (previousChecked) {
