///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    // var usrCBData ="전체^(null),일반^1,벤처^2,기술정상^3,대형^4,스팩^5,스팩합병^6,분할재상장^7,외국기업^8";
    // cmb_INVSTG_CD.CBData =  usrCBData;

    //  기간 from~ to  셋팅
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_BILL_STRT_DD.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 일년 날짜
    edt_BILL_END_DD.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜
    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp1);
    edt_COMITE_STRT_DD.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 일년 날짜
    edt_COMITE_END_DD.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜
    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp2);
};

/**
 * @method
 * @name setBzProcsNo
 * @description set Bz Procs No 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(obj) {
    scwin.clickIsurCd = dts_List.getCellData(Number(obj), "ISUR_CD");
    scwin.clickComNm = dts_List.getCellData(Number(obj), "COM_NM");
    scwin.clickBzProcsNo = dts_List.getCellData(Number(obj), "BZ_PROCS_NO");
};

/**
 * @method
 * @name getBzProcsNo
 * @description get Bz Procs No 처리
 * @returns {void}
 * @hidden N
 */
scwin.getBzProcsNo = function() {
    return scwin.clickBzProcsNo;
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function() {
    if (dts_List.getRowCount() > 0) {
        // 엑셀 로그
        $c.stf.doLogSave("ULDSTF60007.xml", SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, {fileName: "리스트", type: "3"});
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};

/**
 * @method
 * @name getParStdInd
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParStdInd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_STD_IND_CD.getValue(); // 코드값을 포함할 컨트롤
    arrPar[1] = txb_STD_IND_NM.getValue(); // 명칭값을 포함할 컨트롤

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParStdInd
 * @description set Par Std Ind 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParStdInd = function(arrPar) {
    txb_STD_IND_CD.setValue(arrPar[0].STD_IND_CD);
    txb_STD_IND_NM.setValue(arrPar[0].IND_NM);
};

